	title 'QD Lines             GS ROM 2.0'*****************************************************************			   **              LINES		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************		string asis	blanks off	include 'all.macros'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:CORE.GLOBALS1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:RECT.EQUS'	INCLUDE ':QDEquates:SLAB.EQUS'	INCLUDE ':QDEquates:LINE.EQUS';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyErr4	IMPORT CheckPenVis	IMPORT GrabPenSize	IMPORT MinRectToY1	IMPORT NextPatSlice	IMPORT QDStart	IMPORT RgnSave	IMPORT SetFirstDestRef	IMPORT SetNextDestRef	IMPORT TestGPs;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY CallLine	ENTRY GrabPenLoc	ENTRY StabPenLoc;                COPY LINES/LINES****************************************************************** LineTo   (h,v : integer);*****************************************************************	EXPORT LineToLineTo	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3V	equ RTL2+3H	equ V+2	jsr QDStart	jsr GrabPenLoc	lda V,s	; put ending point in	sta Y2	; Y2,X2 and Rect2+4	sta Rect2+4	lda H,s	sta X2	sta Rect2+6	EXPORT ShareLineShareLine		;       	jsr StabPenLoc	jsl CallLine	tax	jmp BusyErr4	ENDP****************************************************************** Line  (dh,dv : integer);*****************************************************************	EXPORT LineLine	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3dv	equ RTL2+3dh	equ dv+2	jsr QDStart	jsr GrabPenLoc	lda Y1	clc	; then calculate end point	adc dv,s	; and point it	sta Y2	; in Y2	sta Rect2+4	; and Rect2+4	lda X1	; Do again for X	clc	adc dh,s	sta X2	sta Rect2+6	bra ShareLine	ENDP****************************************************************** CallLine** Internal routine which calls standard	line or the* appropriate routine attached to the graf port.****************************************************************	EXPORT CallLineCallLine	PROC	Import DrawLine2*              using QDProcs*              using E0Vectors	ldx #512	; test the DirtyDPFlags for picts and pen...	lda <DirtyDPFlags,x	and #TestLineDrawState	cmp #TestLineDrawState	beq DoFasterSetup ; if this is zero, then pen vis/no pictures etc...	jsr TestGPs	bcs NotStandard	jml StdLineNotStandard	phb	; put a byte on the	stack	ldy #o_stdline	; get pointer to new stdline	lda [temp],y	; in a-reg	pha	; push it	iny	; get middle and high byte	lda [temp],y	; of pointer	sta 2,s	; over store middle	byte 2 times	rtl	; go thereDoFasterSetup	jsr GrabPenSize	; don't come back if part is zero	phb	; save the bank register	ldy #O_PnMode	; get the mode down	to zp	lda [PortRef],y	sta FillMode	jmp DrawLine2		ENDP****************************************************************** StdLine******************************************************************	EXPORT iStdLineiStdLine	PROC*              using CoreDATA*              using PicInfo*              using E0Vectors	lda #LineNoun	jsl PutPictStuff	bcc NoPicErr	rtlNoPicErr	jsl AddToPoly	; are we saving a poly	bcc NoPolyErr	rtlNoPolyErr	jsr RgnSave	bcc NoRgnErr	jsl PutLine	bcc NoRgnErr	rtl	; return the errorNoRgnErr		; ****************************************************************** DrawLine** The common line drawing routine.  Draws a line from Point1* to Point2.** By the time control gets here, the Starting and Ending* points are in Y1,X1 and Y2,X2 as well	as Rect2.  The Slab* routines and XSetup use X1 and X2 for	the starting and* stopping points of a horizontal line segment.** We start by building the rectangle that bounds the line and* clipping it.  if the clip results in no rect, we are done.* After the clip, we calculate the slope and initial left and* right edges, using the unclipped points. (Using the clipped* points would not give the right results.)  Finally, we adjust* the left and right edge if the top was clipped by the clipping* amound * slope.  The Line is drawn by	using the vertical limits* obtained from the	clipped rectangle.** Uses Three new variables on Zero Page:*     Slope      a fixed point value, the slope of the line*     LeftEdge   a fixed point value, for the current starting x.*     RightEdge  a fixed point value, for the currend stopping x.*** Modification History:**   18 Mar 86      Checked all compares	and used signed instead of unsigned*                  branches.** 2/27/89	Mensch* Try dropping a newer fastratio routine in...** 3/9/89	Mensch* Added short circut to check pen vis and portloc to ZP****************************************************************	EXPORT DrawLine	Export DrawLine2	Import FastRatioDrawLine		;  	jsr CheckPenVis	; don't come back unless visible	jsr GrabPenSize	; don't come back if part is zero	phb	; save the bank register	jsl PreDrawDrawLine2	jsl SetUpPortRegions;-------------------------------------------;;  Make Line Rect in y1,x1 y2,x2;	lda Y2	; want to draw top to	cmp Y1	; bottom so if Y2 >= Y1	bpl NoYSwap	; then okay	ldy Y1	sty Y2	sta Y1NoYSwap	lda X2	cmp X1	bpl NoXSwap	ldy X1	sta X1	sty X2NoXSwap		; ;------------------------------------------------;;  Now adjust the Line rect by the pen width;  and height;	lda Y2	clc	adc LocalPnSize	sta Y2	lda X2	; adjust X2 by pen size too	clc	adc LocalPnSize+2	sta X2;------------------------------------------------;;  Need to clip Rect2 to intersection of Bounds;  and port rects.;	jsl BMakeMinRect	; clip it	bcc Continue	; if clear then intersection not	jmp NeverMind	; empty else done.;------------------------------------------------;;   Test for Horizontal or Vertical Lines;Continue		; 	jsl ShieldCursor	jsr MinRectToY1	lda Rect2+6	cmp Rect2+2	beq AnHVLine	lda Rect2	cmp Rect2+4	bmi PointsInOrder	beq AnHVLine	ldy Rect2+4	; Top greater than bottom so	sty Rect2	; swap them	sta Rect2+4	lda Rect2+2	; swap x's to match	ldy Rect2+6	sty Rect2+2	sta Rect2+6	bra PointsInOrderAnHVLine	jsl DrawRect	; now get out of here for good	jmp TheEnd;----------------------------------------;;  Initialize the left and right edges;PointsInOrder	lda #$8000	; make fractional parts 1/2	sta LeftEdge	; Gives us free rounding	sta RightEdge	lda Rect2+2	; set up left and right edge	sta LeftEdge+2	; RightEdge = LeftEdge+PenWidth	clc	adc LocalPnSize+2	sta RightEdge+2;------------------------------------------------;;   Caculate the inverted slope (dh/dv)	using;   original points;	pha	; put room for result on stack	pha	lda Rect2+6	sec	sbc Rect2+2	pha	; put delta x on stack	lda Rect2+4	sec	sbc Rect2	pha	; put Delta y on stack	jsr FastRatio;	_FixRatio	; get the ratio	pla	; pull of the ratio	sta Slope	pla	sta Slope+2;----------------------------------------------;;    Now need to adjust the distance between;    left and right	edges.;;----------------------------------------------;;   Calculate the adjust = Pen Height *	Slope;; 3/9/89	Mensch; Modified to see if LocalPnSize is 1 or 2, if so, we do a simple multiply; else we do a standard fix multiply; Also, preset adjust to be the slope...	lda Slope+2	sta Adjust+2	lda Slope	sta Adjust	lda LocalPnSize	cmp #1	; if its 1, the noMult	beq @Mult1Done	cmp #2	; if its 2 do a simple multiply	beq @Multby2; else, just do it the long way...		pha	; Make Room for result	pha	pha	lda #0	pha	lda Slope+2	pha	lda Slope	pha	_FixMul	pla	sta Adjust	pla	sta Adjust+2	bra @Mult1Done@MultBy2	asl Adjust	rol Adjust+2@Mult1Done;-------------------------------------------------------;;   Adjust the Left	and Right edges depending on sign;   magnitude of slope;; WAS:;	lda Slope+2;	asl a	; get sign bit into	carry;	lda Slope+2	; get back orig;	ror a	; divide by 2 preserving sign;	sta SlopeTemp+2;	lda Slope;	ror a;	sta SlopeTemp;	ldx #4;AdjustLoop	lda LeftEdge,x;	clc;	adc SlopeTemp;	sta LeftEdge,x;	lda LeftEdge+2,x;	adc SlopeTemp+2;	sta LeftEdge+2,x;	dex;	dex;	dex;	dex;	bpl AdjustLoop;; IS NOW	lda Slope+2	asl a	; get sign into carry	lda Slope+2	; get back orig	ror a	; rotate putting sign back	tay	; save this in <Y> for a sec...	lda Slope	ror a	tax; Now adjust it...	clc	adc LeftEdge	sta LeftEdge	tya	; get slopetemp+2 back	adc leftEdge+2	sta leftEdge+2		clc	; and do it again...	txa	; get SlopeTemp Back	adc LeftEdge+4	sta LeftEdge+4	tya	adc LeftEdge+6	sta LeftEdge+6; shorter and sweeter	bit Slope+2	; is the slope negative	bmi IsNegative;----------------------------------------------;;    Slope Is Positive;	lda LeftEdge	; subtract adjust from left	sec	; edge	sbc Adjust	sta LeftEdge	lda LeftEdge+2	sbc Adjust+2	sta LeftEdge+2	lda Slope+2	; check to see if slope is less	beq Less1	; than 1	dec RightEdge+2	; if not less sub 1	from right edge	bra SlopeOkLess1	lda LeftEdge	; is less so add slope to left edge	clc	adc Slope	sta LeftEdge	lda LeftEdge+2	adc Slope+2	sta LeftEdge+2	bra SlopeOK;-----------------------------------------------;; Slope Is Negative;IsNegative	lda RightEdge	; subtract adjust from right	sec	; edge	sbc Adjust	sta RightEdge	lda RightEdge+2	sbc Adjust+2	sta RightEdge+2	lda Slope+2	; check to see if slope is more	cmp #$FFFF	; than minus 1	beq More1	inc LeftEdge+2	; not more so add 1	to LeftEdge	bra SlopeOKMore1	lda RightEdge	; is more so add slope to edge	clc	adc Slope	sta RightEdge	lda RightEdge+2	adc Slope+2	sta RightEdge+2SlopeOK		; ;------------------------------------------------;;   Get ready to draw;;------------------- START OF FASTLINE CHANGE --------------------------	;;----- assume they're rectangular unless proven otherwise -----;	lda [RgnPtrA]	ora [RgnPtrB]	cmp #10		bne GoSlow	stz NonRectRegions	;regions are rectangular	jsl SetSlabAdr	; sets up the slab adr on zp	bcs GoSlow	cpx #0	; test if <X> says mode copy...	beq DoModeCopy	cpx #8	; test if mode XOR	bne SkipInit2Regions	lda #$4000	; set bits to flag mode xor fastslab	sta temp	bra SkipInit2Regions	DoModeCopy	lda #$8000	; set bits to flag mode copy fastslab	sta temp	bra SkipInit2Regions	;; ---- End of change ----;GoSlow		jsl Init2Regions	;set up the initial clip buffer	jsl SetSlabAdr	bra SkipKludgeSkipInit2Regions	clcSkipKludge	php	;save state of carry;	;------------------- END OF FASTLINE CHANGE ----------------------------;------------------------------------------------;; If line was cliped, we have to adjust	the; edges.	lda Y1	; if Y1 still equals	cmp Rect2	; Rect2.Top then no	clipping	beq TopOK	; has occured.	sec	; Calculate discard	amount	sbc Rect2	pha	; Make room for result	pha	pha	; push this amount on stack	pea 0	; followed by a zero to represent	pei Slope+2	; discard as a fixed point number	pei Slope	; Then push Slope	_FixMul	plx	; get result in x and y	ply	txa	clc	adc LeftEdge	sta LeftEdge	tya	adc LeftEdge+2	sta LeftEdge+2	txa	clc	adc RightEdge	sta RightEdge	tya	adc RightEdge+2	sta RightEdge+2;------------------------------------------------;;   Find starting point of scan line;TopOK	jsr SetFirstDestRef;---------------------------------------------------;;   Move left and right edge of clipped	line rect;   from X1, X2 to Rect2+2 and Rect2+4;	lda X1	sta Rect2+2	lda Y2	sta Rect2+4	lda X2	sta Rect2+6	txa	; this was result of calc above	;------------------- START OF FASTLINE CHANGE --------------------------	plp	bcc FastLine;------------------- END OF FASTLINE CHANGE ----------------------------;---------------------------------------------------;; The Drawing Loop !;LineLoop		; ;--------------------------------------------------;; Put left and right edges were slab routine will; look for them and	clip to Rect2 at the same time;	lda RightEdge+2	cmp Rect2+6	bmi RightOk	lda Rect2+6RightOK	sta X2	lda LeftEdge+2	cmp Rect2+2	bpl LeftOk	lda Rect2+2LeftOk	sta X1	cmp X2	; if left >= right then	bpl BackHere	; skip the drawing step	jsl XSetup	; set up stuff for slab routines;-----------------------------------------------------------;;   Now have to pull out right slice of	pattern for;   y coordinate;	jsr NextPatSlice	jsl Seek2Regions	jsl ToSlabBackHere	lda CurrentY	inc a	cmp Y2	bpl TheEnd	sta CurrentY	lda LeftEdge	; adjust the left edge	clc	adc Slope	sta LeftEdge	lda LeftEdge+2	adc Slope+2	sta LeftEdge+2	lda RightEdge	; adjust the right edge	clc	adc Slope	sta RightEdge	lda RightEdge+2	adc Slope+2	sta RightEdge+2	jsr SetNextDestRef	jmp LineLoopTheEnd		; 	jsl UnShieldCursorNeverMind		; 	jsl FreePortRegions	plb	; restore the bank register	lda #0	clc	rtl;------------------------START OF FASTLINE STUFF--------------------------------;; The Fast line drawing code;;---------------------------------------------------------------patIndex	equ  CurrentYlineCount	equ  Y2;---------------------------------------------------------------FastLine;	pei  CurrentY	;save the stuff we're going to use;	pei  Y2	;for temporary space	ldx #512	; test for solid patterns	lda <DirtyDPFlags,x	and #SolidPatOK+DirtyFlagsOK	cmp #SolidPatOK+DirtyFlagsOK	bne @DitherPat	jmp FastLineSolidPat@DitherPat	lda  Y2	sec	sbc  CurrentY	sta  lineCount	lda  CurrentY	;find the current index into the FillPat and DrawMask	and  #7	;..tables	asl  a	asl  a	adc  #256	sta  patIndex	tax	Floop 	lda  TheFillPat,x	sta  Pat	lda  TheFillPat+2,x	sta  Pat+2	lda  FillMode	bpl @doTheSlab;; Invert the pattern;@doNOT	lda  Pat	eor  #$FFFF	sta  Pat	lda  Pat+2	eor  #$FFFF	sta  Pat+2@doTheSlab;--------------------------------------------------;; Put left and right edges were slab routine will; look for them and	clip to Rect2 at the same time;	lda RightEdge+2	cmp Rect2+6	bmi @RightOk	lda Rect2+6@RightOK	sta X2	lda LeftEdge+2	cmp Rect2+2	bpl @LeftOk	lda Rect2+2@LeftOk	sta X1	cmp X2	; if left >= right then	bpl @BackHere	; skip the drawing step	jsl XSetup	; set up stuff for slab routines	ldx <startWord	; try to short circut the slabs...	cpx <finishWord	bne @oldSlab	bit temp	; recover our flags	bvs @NewSlabXor	; if overflow clear nomode xor@oldSlab	jsl ToSlab@SlabDone@BackHere	lda  patIndex	clc	adc #4	;inc a four times	and #$011F	sta patIndex	tax	;patIndex in x-reg expected in Floop	dec  lineCount	beq  allDone	lda LeftEdge	; adjust the left edge	clc	adc Slope	sta LeftEdge	lda LeftEdge+2	adc Slope+2	sta LeftEdge+2	lda RightEdge	; adjust the right edge	clc	adc Slope	sta RightEdge	lda RightEdge+2	adc Slope+2	sta RightEdge+2	lda  DestRef	clc	adc  Width	sta  DestRef	bcc  Floop		inc  DestRef+2	pei destref+1	plb	plb	brl  Floop@NewSlabXor; NOTE: <X> has startword and <A> has right mask!	txy	; setup <Y> to point to byte	and <pat	and <leftMask	eor [DestRef],y		;invert & store it	sta [DestRef],y	bra @SlabDone;---------------------------------------------------------------allDone;	pla;	sta  Y2;	pla;	sta  CurrentY	brl  TheEnd	;------------------------------------------------------------------; even faster fastline stuff here...FastLineSolidPat;	pei  CurrentY	;save the stuff we're going to use;	pei  Y2	;for temporary space	lda  Y2	sec	sbc  CurrentY	sta  lineCount	ldx #256 	lda  TheFillPat,x	sta  Pat	sta  Pat+2	lda  FillMode	bpl @doTheSlab;; Invert the pattern;@doNOT	lda  Pat	eor  #$FFFF	sta  Pat	sta  Pat+2@doTheSlab;--------------------------------------------------;; Put left and right edges were slab routine will; look for them and	clip to Rect2 at the same time;	lda RightEdge+2	cmp Rect2+6	bmi @RightOk	lda Rect2+6@RightOK	sta X2	lda LeftEdge+2	cmp Rect2+2	bpl @LeftOk	lda Rect2+2@LeftOk	sta X1	cmp X2	; if left >= right then	bpl @BackHere	; skip the drawing step	jsl XSetup	; set up stuff for slab routines	ldx <startWord	; try to short circut the slabs...	cpx <finishWord	bne @oldSlab	bit temp	; recover our flags	bvs @NewSlabXor	; if overflow clear nomode xor@oldSlab	jsl ToSlab@SlabDone@BackHere		dec  lineCount	beq  allDone	lda LeftEdge	; adjust the left edge	clc	adc Slope	sta LeftEdge	lda LeftEdge+2	adc Slope+2	sta LeftEdge+2	lda RightEdge	; adjust the right edge	clc	adc Slope	sta RightEdge	lda RightEdge+2	adc Slope+2	sta RightEdge+2	lda  DestRef	clc	adc  Width	sta  DestRef	bcc  @doTheSlab		inc  DestRef+2	pei destref+1	plb	plb	bra  @doTheSlab	;------------------------END OF FASTLINE STUFF--------------------------------@NewSlabXor; NOTE: <X> has startword and <A> has right mask!	txy	; setup <Y> to point to byte	and <pat	and <leftMask	eor [DestRef],y		;invert & store it	sta [DestRef],y	bra @SlabDone	ENDP****************************************************************** GrabPenLoc** Takes PnLoc from the port and puts in	Y1,X1 and* at Rect2*****************************************************************	EXPORT GrabPenLocGrabPenLoc	PROC*              using CoreDATA	ldy #O_PnLoc	lda [PortRef],y	sta Y1	sta Rect2	iny	iny	lda [PortRef],y	sta X1	sta Rect2+2	rts	ENDP****************************************************************** StabPenLoc** Xrefs Y2,X2 to PnLoc in the port.*****************************************************************	EXPORT StabPenLocStabPenLoc	PROC*              using CoreDATA	ldy #O_PnLoc	lda Y2	sta [PortRef],y	iny	iny	lda X2	sta [PortRef],y	rts	ENDP********************************************************************************FastRatio	proc Export** Description:	A faster version of intmaths fixratio*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************M1	equ 1origdPage	equ M1+4rts1	equ origDPage+2denom	equ rts1+2Numerator	equ Denom+2Result	equ Numerator+2Quotient	equ M1Remainder	equ Quotient+2	; remainder from first div high word of second	phd	; save the direct page	phx	phx	; room for M1 and M2	tsc	tcd	lda Denom	bne GoOnX	lda #$7FFF	sta Result+2	brl TheEnd	GoOnX	eor Numerator	pha	; save sign info...		lda Numerator	; strip the signes for later	bpl @numPos	eor #$FFFF	inc a	sta Numerator@NumPos	lda Denom	bpl @DenPos	eor #$FFFF	inc a	sta Denom	@DenPos	cmp Numerator	; see if denom is bigger	bge noDiv; first things first, lets start our division off; DoDivide	stz M1	stz M1+2		lda Numerator	sta Quotient	ldy #16	sec	; set carry to start@DivLoop	rol Quotient	; 	rol Quotient+2	sec	lda Quotient+2	sbc Denom	bcc @DecCt	sta Quotient+2@DecCt	dey	bne @DivLoop	rol Quotient	bra ContNoDiv	beq theSame	stz Quotient	lda Numerator	sta Remainder	bra ConttheSame	stz Remainder	lda #1	sta Quotient;; The divide is done nowCont;; Now we do the long divide!	lda Quotient	sta Result+2	stz Result	lda Remainder	; test the remainder for 0	beq LongDivDone		pha	pha	pha	pha		pha	pea 0		pea 0	lda Denom	pha	_LongDivide	pla	sta Result	pla	pla	plaLongDivDone	pla	; get sign off stack	bpl theEnd	lda #0	sec	sbc Result	sta Result	lda #0	sbc Result+2	sta Result+2theEnd	plx	; get our shit off the stack!	plx	pld	; get the direct page	lda 1,s	; get the return address	sta 5,s	; and move it down...	pla	pla	rts		EndP		END